B.aug=s(["\u516d\u7a2e\u6536\u652f\u5716\u8868\u6539\u7528\u5168\u65b0\u7684\u8c93\u54aa\u683c\u72c0\u52d5\u756b\uff0c\u4f9d\u6536\u5165\u8207\u652f\u51fa\u6bd4\u4f8b\u5207\u63db\u5c0d\u61c9\u756b\u9762\u3002","\u5713\u9905\u3001\u74b0\u5f62\u3001\u5b58\u9322\u7f50\u3001\u67f1\u72c0\u3001\u5929\u5e73\u8207\u7f50\u982d\u5716\u5747\u4f7f\u7528\u5404\u81ea\u7684\u6bd4\u4f8b\u52d5\u756b\uff0c\u4e0d\u518d\u5171\u7528\u55ae\u4e00\u5713\u74b0\u6548\u679c\u3002","\u91cd\u65b0\u6821\u6b63\u6bcf\u4e00\u683c\u7684\u900f\u660e\u908a\u754c\u8207\u4e3b\u9ad4\u57fa\u6e96\uff0c\u6e1b\u5c11\u5207\u63db\u6642\u4f4d\u79fb\u6216\u9732\u51fa\u76f8\u9130\u5716\u7247\u3002","\u66f4\u65b0\u6536\u652f\u5716\u8868\u9078\u55ae\u4e2d\u7684\u74b0\u5f62\u8207\u4e0d\u986f\u793a\u5716\u793a\u3002"],t.s)
B.apV=s(["All six cashflow chart modes now use new cat sprite artwork selected by income and expense ratios.","Pie, donut, savings bank, bar, balance, and food-can modes each use their own ratio animation.","Recalibrated transparent bounds and subject anchors to reduce frame drift and neighboring-image bleed.","Updated the donut and hidden-mode icons in the cashflow chart selector."],t.s)
B.VI=new A.cx("v1.2.135+143","\u6536\u652f\u5716\u8868\u63db\u4e0a\u6bd4\u4f8b\u9023\u52d5\u8c93\u54aa\u52d5\u756b","Ratio-driven cat artwork for cashflow charts",B.aug,B.apV)
B.afU=s(["\u6539\u5584 Android APK \u5728\u90e8\u5206\u624b\u6a5f\u8207\u6a21\u64ec\u5668\u4e0a\u7684\u5b89\u88dd\u76f8\u5bb9\u6027\u3002","\u4fee\u6b63\u884c\u7a0b\u8207\u5de5\u4f5c\u8cc7\u8a0a\u5361\u6578\u91cf\u6587\u5b57\u7684 Android \u767d\u8272\u6b98\u5f71\u3002","\u88dc\u9f4a\u63d0\u9192\u6717\u8b80\u98a8\u683c\u7684\u7e41\u9ad4\u4e2d\u6587\u8207\u82f1\u6587\u6a19\u7c64\u3002"],t.s)
B.abI=s(["Improved Android APK installation compatibility on more phones and emulators.","Fixed white text ghosting in schedule and work summary counts on Android.","Completed Traditional Chinese and English labels for reminder voice styles."],t.s)
B.Vs=new A.cx("v1.2.134+142","Android \u5b89\u88dd\u8207\u986f\u793a\u76f8\u5bb9\u6027\u6539\u5584","Android installation and display compatibility",B.afU,B.abI)
B.acp=s(["\u6536\u5165\u8a18\u9304\u7684\u300c\u4ed8\u6b3e\u65b9\u5f0f\u300d\u6539\u70ba\u300c\u5165\u5e33\u65b9\u5f0f\u300d\u3002","\u5c0f\u55b5\u624b\u5feb\u901f\u9810\u89bd\u3001\u9010\u9805\u8f38\u5165\u8207\u624b\u52d5\u8a18\u5e33\u5747\u6703\u986f\u793a\u5c0d\u61c9\u6b04\u4f4d\u540d\u7a31\u3002","\u652f\u51fa\u8207\u9810\u4ed8\u652f\u51fa\u4ecd\u7dad\u6301\u300c\u4ed8\u6b3e\u65b9\u5f0f\u300d\u3002"],t.s)
B.afR=s(["Income records now show Deposit method instead of Payment method.","Quick capture, guided entry, and manual ledger forms use the matching label.","Expense and advance-expense records continue to show Payment method."],t.s)
B.VE=new A.cx("v1.2.133+141","\u6536\u5165\u6b04\u4f4d\u540d\u7a31\u66f4\u6e05\u695a","Clearer field labels for income records",B.acp,B.afR)
B.amm=s(["\u555f\u52d5\u54c1\u724c\u9801\u6539\u70ba\u4f9d\u88dd\u7f6e\u6bd4\u4f8b\u9078\u64c7\u7684\u5b8c\u6574\u55ae\u5f35\u5716\u7247\uff0c\u4e0d\u518d\u5206\u5225\u8f09\u5165\u5c0f\u8c93\u8207 logo\u3002","\u884c\u7a0b\u898f\u5283\u8207\u5de5\u4f5c\u8ffd\u8e64\u6458\u8981\u8cc7\u8a0a\u5361\u65b0\u589e\u5c0e\u89bd\u7bad\u982d\uff0c\u53ef\u76f4\u63a5\u524d\u5f80\u5c0d\u61c9\u6e05\u55ae\u3002","\u56db\u500b\u4e3b\u8981\u9801\u9762\u52a0\u5165\u5404\u81ea\u7368\u7acb\u7684\u9996\u6b21\u63a2\u7167\u71c8\u5c0e\u89bd\uff0c\u7531\u81ea\u8a02\u540d\u7a31\u7684\u5c0f\u55b5\u624b\u9010\u6b65\u4ecb\u7d39\u529f\u80fd\u3002","\u6bcf\u4f4d\u6703\u54e1\u5728\u6bcf\u53f0\u88dd\u7f6e\u7684\u5c0e\u89bd\u9032\u5ea6\u6703\u7368\u7acb\u4fdd\u5b58\uff0c\u770b\u904e\u5f8c\u4e0d\u6703\u53cd\u8986\u51fa\u73fe\u3002","\u6d6a\u55b5\u8207\u5c0f\u55b5\u624b\u4e92\u76f8\u81ea\u6211\u4ecb\u7d39\u6642\uff0c\u6703\u6b63\u78ba\u4f7f\u7528\u6703\u54e1\u8a2d\u5b9a\u7684\u5c0f\u55b5\u624b\u540d\u7a31\u3002","\u8a18\u5e33\u7ba1\u7406\u7684\u74b0\u5f62\u5716\u6539\u7528\u65b0\u8c93\u54aa\u5716\u6848\uff0c\u74b0\u5e36\u6703\u4f9d\u6536\u5165\u8207\u652f\u51fa\u6bd4\u4f8b\u52d5\u614b\u8b8a\u8272\u3002"],t.s)
B.acf=s(["The startup brand page now uses one flattened image per device orientation instead of loading separate cat and logo assets.","Schedule and Work Tracking summary cards now include arrows that navigate directly to their related lists.","Each of the four main pages has an independent first-use spotlight tour led by the custom-named assistant.","Tour completion is stored separately for each member and device, so completed guidance does not repeat.","Stray Cat introductions now use the assistant name selected by the member.","The ledger donut mode now uses the new cat artwork, with an animated ring colored by income and expense proportions."],t.s)
B.VV=new A.cx("v1.2.132+140","\u8cc7\u8a0a\u5361\u5c0e\u89bd\u3001\u65b0\u624b\u6559\u5b78\u3001\u52d5\u614b\u8c93\u54aa\u5716\u8868\u8207\u55ae\u5716\u555f\u52d5\u756b\u9762","Navigation, onboarding, cat charts, and a single-image startup screen",B.amm,B.acf)
B.ans=s(["Logo \u555f\u52d5\u756b\u9762\u8abf\u6574\u70ba\u7d04\u4e94\u79d2\uff0c\u9ede\u64ca\u6216\u89f8\u78b0\u756b\u9762\u53ef\u76f4\u63a5\u9032\u5165\u7248\u672c\u78ba\u8a8d\u968e\u6bb5\u3002","Android \u6b63\u5f0f\u7248\u6539\u7528\u542b Supabase \u516c\u958b\u9023\u7dda\u53c3\u6578\u7684\u5c08\u7528\u5efa\u7f6e\u6d41\u7a0b\uff0c\u4fee\u6b63\u767b\u5165\u5f8c\u9032\u5165\u793a\u7bc4\u6a21\u5f0f\u3002","Android \u884c\u7a0b\u63d0\u9192\u6539\u7528\u65b0\u7684\u6e05\u695a\u8c93\u53eb\u8072\u3002"],t.s)
B.amQ=s(["The Logo startup screen now stays for about five seconds and can be skipped by tapping or clicking it.","Android production builds now use the dedicated Supabase-enabled build flow, fixing the demo-mode fallback after sign-in.","Android reminders now use the new, clearer cat sound."],t.s)
B.Vw=new A.cx("v1.2.130+138","Android \u6b63\u5f0f\u9023\u7dda\u8207\u555f\u52d5\u756b\u9762\u66f4\u65b0","Android production connection and startup update",B.ans,B.amQ)
B.aiv=s(["\u624b\u52d5\u65b0\u589e\u7684\u65e5\u671f\u6b04\u4f4d\u73fe\u5728\u9810\u8a2d\u70ba\u88dd\u7f6e\u7576\u5929\uff0c\u4e0d\u518d\u53d7\u5916\u5c64\u6708\u66c6\u9078\u53d6\u65e5\u671f\u5f71\u97ff\u3002","\u5c0f\u55b5\u624b\u53ef\u8fa8\u8b58\u300c8\u670819\u300d\u7b49\u7701\u7565\u65e5\u6216\u865f\u7684\u65e5\u671f\u8aaa\u6cd5\u3002","\u300c\u5348\u9910\u8cbb\u752890\u300d\u7b49\u7c21\u77ed\u8a9e\u53e5\u6703\u6b63\u78ba\u5206\u96e2\u8a18\u5e33\u540d\u7a31\u8207\u91d1\u984d\u3002","\u65b0\u7248\u555f\u52d5\u9801\u3001\u55ae\u9031\u8207\u5c55\u958b\u6708\u66c6\u3001\u5de6\u5074\u5e63\u5225\u9078\u64c7\u4e00\u4f75\u516c\u958b\u3002","Android \u63d0\u9192\u6539\u7528 worCat \u8c93\u54aa\u5716\u793a\u8207\u77ed\u8c93\u53eb\u8072\u3002","Android \u53f3\u4e0a\u89d2\u65b0\u589e\u63d0\u9192\u6717\u8b80\u8a2d\u5b9a\uff0c\u53ef\u9078\u64c7\u50c5\u8c93\u53eb\u3001\u6a19\u6e96\u3001\u53ef\u611b\u3001\u6d3b\u529b\u6216\u6eab\u67d4\u98a8\u683c\u3002"],t.s)
B.ajU=s(["Manual entry date fields now default to the device date instead of inheriting an accidentally selected calendar day.","The assistant recognizes dates such as August 19 without requiring a spoken day suffix.","Short phrases such as lunch expense 90 now separate the ledger title and amount correctly.","The updated launch flow, weekly and expanded calendars, and left-side currency selector are included in this release.","Android reminders now use the worCat icon and a short cat sound.","Android adds per-device reminder voice styles: meow only, standard, cute, energetic, or gentle."],t.s)
B.VT=new A.cx("v1.2.129+137","\u65e5\u671f\u8f38\u5165\u3001\u8a9e\u97f3\u89e3\u6790\u8207 Android \u63d0\u9192\u5f37\u5316","Date entry, speech parsing, and Android reminders",B.aiv,B.ajU)
B.amX=s(["\u6708\u66c6\u9810\u8a2d\u53ea\u986f\u793a\u9078\u53d6\u65e5\u671f\u6240\u5728\u7684\u4e00\u9031\uff0c\u8b93\u624b\u6a5f\u65e5\u671f\u683c\u66f4\u5bec\u3001\u66f4\u5bb9\u6613\u9ede\u9078\u3002","\u624b\u6a5f\u8207\u5e73\u677f\u53ef\u5de6\u53f3\u6ed1\u52d5\u5207\u63db\u524d\u5f8c\u9031\uff0c\u4e26\u986f\u793a\u76ee\u524d\u662f\u672c\u6708\u7b2c\u5e7e\u9031\u3002","\u6309\u4e0b\u5c55\u958b\u6309\u9215\u5373\u53ef\u67e5\u770b\u6574\u6708\uff0c\u518d\u6b21\u6309\u4e0b\u53ef\u6536\u5408\u56de\u55ae\u9031\u6a21\u5f0f\u3002","\u65e5\u671f\u683c\u5c3a\u5bf8\u3001\u5167\u8ddd\u8207\u9593\u8ddd\u6703\u4f9d\u624b\u6a5f\u3001\u5e73\u677f\u53ca\u96fb\u8166\u756b\u9762\u81ea\u52d5\u8abf\u6574\u3002"],t.s)
B.ao0=s(["The calendar defaults to the selected week, giving mobile day cells more room and larger tap targets.","Phones and tablets can swipe between weeks while showing the current week of the month.","The expand control reveals the full month and collapses back to one week on demand.","Day cell sizing, padding, and spacing now adapt to phone, tablet, and desktop layouts."],t.s)
